// Temporary diagnostic: find which GPIO pair the SSD1306 is wired to.
// Skips 19/20 (USB D-/D+), 43/44 (UART0) and 26-32 (SPI flash) so the sweep
// cannot kill its own serial link or crash on flash pins.
#include <Arduino.h>
#include <Wire.h>

namespace {

constexpr int kCandidatePins[] = {8,  9,  4,  5,  6,  7,  10, 11, 12, 13,
                                  14, 15, 16, 17, 18, 21, 1,  2,  3,  38,
                                  39, 40, 41, 42, 45, 46, 47, 48};
constexpr std::uint8_t kProbeAddresses[] = {0x3CU, 0x3DU};

bool probe(int sda, int scl, std::uint8_t address) {
    Wire.end();
    if (!Wire.setPins(sda, scl)) {
        return false;
    }
    if (!Wire.begin()) {
        return false;
    }
    Wire.setTimeOut(20U);
    Wire.beginTransmission(address);
    return Wire.endTransmission() == 0;
}

}  // namespace

void setup() {
    Serial.begin(115200);
    delay(3000);
    Serial.println();
    Serial.println("=== SSD1306 pin sweep ===");

    int hits = 0;
    for (int sda : kCandidatePins) {
        for (int scl : kCandidatePins) {
            if (sda == scl) {
                continue;
            }
            for (std::uint8_t address : kProbeAddresses) {
                if (probe(sda, scl, address)) {
                    Serial.printf("HIT  SDA=GPIO%d  SCL=GPIO%d  addr=0x%02X\n", sda, scl,
                                  static_cast<unsigned>(address));
                    ++hits;
                }
            }
        }
    }

    Serial.printf("=== sweep done, %d hit(s) ===\n", hits);
    if (hits == 0) {
        Serial.println("No I2C device answered. Check VCC/GND and the SDA/SCL wires.");
    }
}

void loop() {
    delay(1000);
}

